#!/usr/bin/env python3
"""Pack the existing empty-handed standing drawings, preserving every walk pixel."""
from pathlib import Path
import hashlib,json,subprocess
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]
meta=json.loads(subprocess.check_output(['node','--input-type=module','-e',"import {SHEETS} from './src/sprite-meta-hd.js';console.log(JSON.stringify({shane:SHEETS.shane,natalie:SHEETS.natalie}));"],cwd=ROOT,text=True))
source=ROOT/'assets/player-directions-base.webp';art=Image.open(source).convert('RGBA');rows=[];overrides={};proof=Image.new('RGBA',(560,360))
for index,(who,y) in enumerate([('shane',680),('natalie',1700)]):
 original=ROOT/f'assets/hd-{who}.webp';old=Image.open(original).convert('RGBA');m=meta[who]
 cut=art.crop((840,y,1120,y+340));bounds=cut.getchannel('A').point(lambda a:255 if a>=32 else 0).getbbox();assert bounds
 f=m['idle'][0];before=old.crop((f['x'],f['y'],f['x']+f['w'],f['y']+f['h']));b=before.getchannel('A').point(lambda a:255 if a>=32 else 0).getbbox();targetheight=b[3]-b[1];scale=targetheight/(bounds[3]-bounds[1]);footOffset=b[3]-f['ay']
 tile=cut.crop(bounds);size=(round(tile.width*scale),round(tile.height*scale));tile=tile.resize(size,Image.Resampling.LANCZOS);sourceax=(140-bounds[0])*scale
 width=2*round(max(sourceax,size[0]-sourceax)+8);height=max(f['h'],round(f['ay']+footOffset)+6)
 im=Image.new('RGBA',(max(old.width,width*len(m['idle'])),old.height+height));im.paste(old,(0,0))
 packed=[]
 for i,frame in enumerate(m['idle']):
  ax=width/2;ay=f['ay'];at=(round(ax-sourceax),round(ay+footOffset-size[1]));assert min(at)>=0 and at[0]+size[0]<=width and at[1]+size[1]<=height
  im.alpha_composite(tile,(i*width+at[0],old.height+at[1]));packed.append({'x':i*width,'y':old.height,'w':width,'h':height,'ax':ax,'ay':ay})
 for frame in m['walk']:
  box=(frame['x'],frame['y'],frame['x']+frame['w'],frame['y']+frame['h']);assert im.crop(box).tobytes()==old.crop(box).tobytes()
 out=ROOT/f'assets/hd-{who}-empty-idle.webp';im.save(out,'WEBP',lossless=True,method=6,exact=True);overrides[who]={**m,'w':im.width,'h':im.height,'idle':packed}
 proof.alpha_composite(cut,(index*280,10))
 rows.append({'id':who,'source':'assets/player-directions-base.webp','sourceSha256':hashlib.sha256(source.read_bytes()).hexdigest(),'sourceCell':[840,y,280,340],'sourceBounds':bounds,'scale':scale,'packedBodyPixels':targetheight,'original':'assets/hd-'+who+'.webp','originalSha256':hashlib.sha256(original.read_bytes()).hexdigest(),'output':'assets/'+out.name,'outputSha256':hashlib.sha256(out.read_bytes()).hexdigest(),'outputBytes':out.stat().st_size,'frames':len(m['idle']),'walkPixelsUnchanged':True})
proof.save(ROOT/'assets/owner-idle-concepts/approved-standing-poses.png')
(ROOT/'assets/owner-idle-concepts/manifest.json').write_text(json.dumps({'version':1,'method':'Reuse the previously authored empty-handed front standing poses from the final cells of the base action sheet. Static pose; idle slots repeat that drawing. No newly generated or manufactured walking/idle artwork.','characters':rows},indent=2)+'\n')
(ROOT/'src/content/owner-empty-idle-meta.js').write_text('// Generated by tools/bake-owner-empty-idle.py.\nexport const OWNER_EMPTY_IDLE_META = '+json.dumps(overrides)+';\n')
print(json.dumps(rows))
